(44, 1113, 9, 26, 1, 1, 1, 'ঢাকায় পুলিশের গাড়িতে আগুনের ঘটনায় দুজন গ্রেপ্তার', '', NULL, 'public/postimages/654aaa12de891.png', 'এই সব কী! রোজ বাসে আগুন দিচ্ছেন কেন? কখনো কখনো যাত্রীদের নামিয়ে দিয়ে, কখনো-বা ভেতরে ঘুমন্ত বাসের চালক বা সহকারীকে রেখে রোজ বাসে আগুন দেওয়ার মানে কী! কী অর্জন করতে চাইছেন এসব থেকে!', '<p>এই সব কী! রোজ বাসে আগুন দিচ্ছেন কেন? কখনো কখনো যাত্রীদের নামিয়ে দিয়ে, কখনো-বা ভেতরে ঘুমন্ত বাসের চালক বা সহকারীকে রেখে রোজ বাসে আগুন দেওয়ার মানে কী! কী অর্জন করতে চাইছেন এসব থেকে!<br>', 'nbbvvn', NULL, 1, 1, 1, 1, '07-11-2023', 'November', NULL, NULL, NULL, NULL, NULL, NULL),
(45, 1113, 2, 3, 1, 1, 1, 'আশুলিয়ায় বন্ধ ৬০ পোশাক কারখানা, ১২ মামলায় আসামি সাড়ে ৩ হাজার', NULL, NULL, 'public/postimages/6550847775045.png', 'ন্যূনতম মজুরি প্রত্যাখ্যান করে পোশাকশ্রমিকদের চলমান আন্দোলনের জেরে ঢাকার অদূরে সাভারের আশুলিয়ায় আজ রোববার ৬০টি পোশাক কারখানা বন্ধ আছে। গতকাল শনিবার সাভার, আশুলিয়া ও ধামরাইয়ে মোট বন্ধ কারখানার সংখ্যা ছিল ১৩০।', '<p>ন্যূনতম মজুরি প্রত্যাখ্যান করে পোশাকশ্রমিকদের চলমান আন্দোলনের জেরে ঢাকার অদূরে সাভারের আশুলিয়ায় আজ রোববার ৬০টি পোশাক কারখানা বন্ধ আছে। গতকাল শনিবার সাভার, আশুলিয়া ও ধামরাইয়ে মোট বন্ধ কারখা', 'dhaka', NULL, 1, 1, 1, 1, '07-11-2023', 'November', NULL, NULL, NULL, NULL, NULL, '45/আশুলিয়ায়-বন্ধ-৬০-পোশাক-কারখানা,-১২-মামলায়-আসামি-সাড়ে-৩-হাজার'),
(46, 1113, 2, 3, 1, 1, 1, '১৬ দিন ধরে বিএনপি কার্যালয়ে ঝুলছে তালা, সামনে পুলিশ', NULL, NULL, 'public/postimages/655084deab5d8.png', 'রাজধানীর নয়াপল্টনে বিএনপির কেন্দ্রীয় কার্যালয়ের মূল ফটকে ১৬ দিন ধরে তালা ঝুলছে। কার্যালয়ের সামনে অবস্থান করছে পুলিশ।আজ রোববার সকাল ১০টার দিকে বিএনপির কেন্দ্রীয় কার্যালয় এলাকায় গিয়ে এমন চিত্র দেখা গেছে।', '<p>রাজধানীর নয়াপল্টনে বিএনপির কেন্দ্রীয় কার্যালয়ের মূল ফটকে ১৬ দিন ধরে তালা ঝুলছে। কার্যালয়ের সামনে অবস্থান করছে পুলিশ।<span style=\"font-size: 1rem;\">আজ রোববার সকাল ১০টার দিকে বিএনপির কেন্', 'dhaka', NULL, 1, 1, 1, 1, '07-11-2023', 'November', NULL, NULL, NULL, NULL, NULL, '46/১৬-দিন-ধরে-বিএনপি-কার্যালয়ে-ঝুলছে-তালা,-সামনে-পুলিশ'),
(47, 1113, 2, 3, 1, 1, 1, 'নারায়ণগঞ্জে পার্কিং করা গাড়ি ভাঙচুর, আগুন', NULL, NULL, 'public/postimages/6550853da1509.png', 'নারায়ণগঞ্জ সদর উপজেলার সিদ্ধিরগঞ্জে পার্কিং করা একটি গাড়ি ভাঙচুর ও আগুন দেওয়ার ঘটনা ঘটেছে। গতকাল শনিবার গভীর রাতে এ ঘটনা ঘটে। তবে এতে কোনো হতাহতের ঘটনা ঘটেনি।', '<p>নারায়ণগঞ্জ সদর উপজেলার সিদ্ধিরগঞ্জে পার্কিং করা একটি গাড়ি ভাঙচুর ও আগুন দেওয়ার ঘটনা ঘটেছে। গতকাল শনিবার গভীর রাতে এ ঘটনা ঘটে। তবে এতে কোনো হতাহতের ঘটনা ঘটেনি।</p><p><span style=\"font-size:', 'dhaka', NULL, 1, 1, 1, 1, '07-11-2023', 'November', NULL, NULL, NULL, NULL, NULL, '47/নারায়ণগঞ্জে-পার্কিং-করা-গাড়ি-ভাঙচুর,-আগুন'),
(48, 1113, 5, 7, 1, 1, 1, 'রাজধানীতে অবরোধের সমর্থনে বিএনপি ও অঙ্গসংগঠনের ঝটিকা মিছিল', NULL, NULL, 'public/postimages/65509feeda191.png', 'চতুর্থ দফা অবরোধের প্রথম দিন আজ রোববার রাজধানীর বিভিন্ন স্থানে ঝটিকা মিছিল করেছেন বিএনপিসহ দলটির অঙ্গসংগঠনের নেতা-কর্মীরা। এ সময় তাঁরা কোথাও কোথাও সংক্ষিপ্ত সমাবেশও করেন। বিএনপি ও অঙ্গসংগঠনগুলোর দেওয়া প্রেস বিজ্ঞপ্তিতে এ তথ্য জানা যায়।', '<p>চতুর্থ দফা অবরোধের প্রথম দিন আজ রোববার রাজধানীর বিভিন্ন স্থানে ঝটিকা মিছিল করেছেন বিএনপিসহ দলটির অঙ্গসংগঠনের নেতা-কর্মীরা। এ সময় তাঁরা কোথাও কোথাও সংক্ষিপ্ত সমাবেশও করেন। বিএনপি ও অঙ্গসংগঠ', 'dhaka', NULL, 1, 1, 1, 1, '07-11-2023', 'November', NULL, NULL, NULL, NULL, NULL, '48/রাজধানীতে-অবরোধের-সমর্থনে-বিএনপি-ও-অঙ্গসংগঠনের-ঝটিকা-মিছিল'),
(49, 1113, 8, 12, 1, 1, 1, 'কখনো স্কুলেই যাননি এই নায়িকা', NULL, NULL, 'public/postimages/655099fbdf238.png', 'মাত্র ১৪ বছর বয়সে মডেলিং শুরু করেন ক্যাটরিনা। এর কিছুদিন পরই লন্ডনভিত্তিক নির্মাতা কাইজাদ গুস্তাবের চোখে পড়েন। তাঁর পরিচালনায় ২০০৩ সালে ‘বুম’ সিনেমায় সুযোগ পান ক্যাটরিনা। এ সিনেমায় ছিলেন অমিতাভ বচ্চনও', '<p><span style=\"color: rgb(18, 18, 18); font-family: Shurjo, SolaimanLipi, &quot;Siyam Rupali&quot;, Roboto, Arial, Helvetica, monospace; font-size: 18px;\">মাত্র ১৪ বছর বয়সে মডেলিং শুরু করেন', 'dhaka', NULL, 1, 1, 1, 1, '07-11-2023', 'November', NULL, NULL, NULL, NULL, NULL, '49/কখনো-স্কুলেই-যাননি-এই-নায়িকা'),
(50, 1113, 2, 3, 1, 1, 1, 'সারা দেশে ১৫২ প্লাটুন বিজিবি মোতায়েন', NULL, NULL, 'public/postimages/655085b39e5e9.png', 'আইনশৃঙ্খলা পরিস্থিতি নিয়ন্ত্রণে সারা দেশে ১৫২ প্লাটুন বিজিবি মোতায়েন করা হয়েছে।আজ রোববার সকালে বর্ডার গার্ড বাংলাদেশের (বিজিবি) পক্ষ থেকে গণমাধ্যমে পাঠানো খুদে বার্তায় এ তথ্য জানানো হয়।', '<p>আইনশৃঙ্খলা পরিস্থিতি নিয়ন্ত্রণে সারা দেশে ১৫২ প্লাটুন বিজিবি মোতায়েন করা হয়েছে।<span style=\"font-size: 1rem;\">আজ রোববার সকালে বর্ডার গার্ড বাংলাদেশের (বিজিবি) পক্ষ থেকে গণমাধ্যমে পাঠানো খু', 'nbbvvn', NULL, 1, 1, 1, 1, '07-11-2023', 'November', NULL, NULL, NULL, NULL, NULL, '50/সারা-দেশে-১৫২-প্লাটুন-বিজিবি-মোতায়েন'),
(51, 1113, 2, 3, 1, 1, 1, 'মিরপুরে আড়াই ঘণ্টা পর রাস্তা ছাড়লেন পোশাকশ্রমিকেরা', NULL, NULL, 'public/postimages/65508617984ee.png', 'আড়াই ঘণ্টা পর রাজধানীর মিরপুর-১৩ ও মিরপুর-১০ নম্বর এলাকার রাস্তা ছাড়েন পোশাক কারখানার শ্রমিকেরা।আজ রোববার সকাল ৮টা থেকে শ্রমিকেরা মিরপুর ১৩ নম্বর সড়কের দুই পাশে অবস্থান করে বিক্ষোভ শুরু করেন। সকাল সাড়ে ১০টার দিকে তাঁরা সরে যান বলে জানিয়েছে পুলিশ।', '<p>আড়াই ঘণ্টা পর রাজধানীর মিরপুর-১৩ ও মিরপুর-১০ নম্বর এলাকার রাস্তা ছাড়েন পোশাক কারখানার শ্রমিকেরা।<span style=\"font-size: 1rem;\">আজ রোববার সকাল ৮টা থেকে শ্রমিকেরা মিরপুর ১৩ নম্বর সড়কের দুই প', 'dhaka', NULL, 1, 1, 1, 1, '07-11-2023', 'November', NULL, NULL, NULL, NULL, NULL, '51/মিরপুরে-আড়াই-ঘণ্টা-পর-রাস্তা-ছাড়লেন-পোশাকশ্রমিকেরা'),
(52, 1113, 2, 3, 1, 1, 1, 'বগুড়ায় মহাসড়ক অবরোধ করে বিএনপি নেতা-কর্মীদের বিক্ষোভ', NULL, NULL, 'public/postimages/6550869161c9b.png', 'বিএনপির ডাকা চতুর্থ দফায় সারা দেশে ৪৮ ঘণ্টার সড়ক, রেল ও নৌপথ অবরোধের প্রথম দিন বগুড়ায় মহাসড়কে অবস্থান নিয়ে বিক্ষোভ করেছেন দলটির নেতা-কর্মীরা। আজ রোববার সকাল থেকে ঢাকা-রংপুর মহাসড়কের বগুড়ার শাজাহানপুর উপজেলার বনানী-লিচুতলায় বাইপাস সড়কে অবস্থান নিয়ে বিক্ষোভ করছেন তাঁরা।', '<p>বিএনপির ডাকা চতুর্থ দফায় সারা দেশে ৪৮ ঘণ্টার সড়ক, রেল ও নৌপথ অবরোধের প্রথম দিন বগুড়ায় মহাসড়কে অবস্থান নিয়ে বিক্ষোভ করেছেন দলটির নেতা-কর্মীরা। আজ রোববার সকাল থেকে ঢাকা-রংপুর মহাসড়কের বগুড়ার', 'dhaka', NULL, 1, 1, 1, 1, '07-11-2023', 'November', NULL, NULL, NULL, NULL, NULL, '52/বগুড়ায়-মহাসড়ক-অবরোধ-করে-বিএনপি-নেতা-কর্মীদের-বিক্ষোভ'),
(53, 1113, 2, 3, 1, 1, 1, 'গাজীপুরে শ্রমিক-পুলিশ সংঘর্ষে আহত আরেক শ্রমিকের মৃত্যু', NULL, NULL, 'public/postimages/655087031675c.png', 'গাজীপুর মহানগরীর কোনাবাড়ীর জরুন এলাকায় শ্রমিক ও পুলিশের মধ্যে সংঘর্ষের ঘটনায় আহত আরেক শ্রমিক মারা গেছেন। ঢাকা মেডিকেল কলেজ (ঢামেক) হাসপাতালে চিকিৎসাধীন অবস্থায় গতকাল শনিবার দিবাগত রাত সাড়ে ১২টার দিকে মো. জালাল উদ্দিন (৪০) নামের ওই শ্রমিকের মৃত্যু হয়।', '<p>গাজীপুর মহানগরীর কোনাবাড়ীর জরুন এলাকায় শ্রমিক ও পুলিশের মধ্যে সংঘর্ষের ঘটনায় আহত আরেক শ্রমিক মারা গেছেন। ঢাকা মেডিকেল কলেজ (ঢামেক) হাসপাতালে চিকিৎসাধীন অবস্থায় গতকাল শনিবার দিবাগত রাত সাড়ে', 'dhaka', NULL, 1, 1, 1, 1, '07-11-2023', 'November', NULL, NULL, NULL, NULL, NULL, '53/গাজীপুরে-শ্রমিক-পুলিশ-সংঘর্ষে-আহত-আরেক-শ্রমিকের-মৃত্যু'),
(54, 1113, 2, 3, 1, 1, 1, 'মিরপুরে রাস্তায় নেমে পোশাকশ্রমিকদের বিক্ষোভ', NULL, NULL, 'public/postimages/655087dab1052.png', 'রাজধানীর মিরপুর–১০, ১৩ ও পল্লবী এলাকার রাস্তা অবরোধ করে বিক্ষোভ করছেন পোশাক কারখানার কয়েক শ শ্রমিক। আজ রোববার সকাল ৮টা থেকে শ্রমিকেরা মিরপুর–১৩ নম্বর সড়কের দুই পাশে অবস্থান করে বিক্ষোভ শুরু করেন।', '<p>রাজধানীর মিরপুর–১০, ১৩ ও পল্লবী এলাকার রাস্তা অবরোধ করে বিক্ষোভ করছেন পোশাক কারখানার কয়েক শ শ্রমিক। আজ রোববার সকাল ৮টা থেকে শ্রমিকেরা মিরপুর–১৩ নম্বর সড়কের দুই পাশে অবস্থান করে বিক্ষোভ শুর', 'dhaka', NULL, 1, 1, 1, 1, '07-11-2023', 'November', NULL, NULL, NULL, NULL, NULL, '54/মিরপুরে-রাস্তায়-নেমে-পোশাকশ্রমিকদের-বিক্ষোভ'),
(55, 1113, 2, 3, 1, 1, 1, '‘এক হাতে রিকশা চালাইতে কষ্ট অইলেও সম্মান নিয়া চলতাম পারি’', NULL, NULL, 'public/postimages/6550885af30e7.png', 'তখন তিনি পঞ্চম শ্রেণির ছাত্র। একদিন স্কুল থেকে বাড়িতে ফেরার পথে দ্রুতগামী ট্রাক ধাক্কা দিয়ে তাঁকে রাস্তার ওপর ফেলে দেয়। ডান হাতটি ভেঙে থেঁতলে-মুচড়ে যায়। এরপর কবজি থেকে হাতটাকে কেটে ফেলতে হয়। সেই দুর্ঘটনা শুধু তাঁর শৈশবকেই তছনছ করেনি, স্থায়ী কষ্টের মধ্যে ফেলে দিয়েছে।', '<p>তখন তিনি পঞ্চম শ্রেণির ছাত্র। একদিন স্কুল থেকে বাড়িতে ফেরার পথে দ্রুতগামী ট্রাক ধাক্কা দিয়ে তাঁকে রাস্তার ওপর ফেলে দেয়। ডান হাতটি ভেঙে থেঁতলে-মুচড়ে যায়। এরপর কবজি থেকে হাতটাকে কেটে ফেলতে হ<span style=\"font-size: 1rem;\">তখন তিনি পঞ্চম শ্রেণির ছাত্র। একদিন স্কুল থেকে বাড়িতে ফেরার পথে দ্রুতগামী ট্রাক ধাক্কা দিয়ে তাঁকে রাস্তার ওপর ফেলে দেয়। ডান হাতটি ভেঙে থেঁতলে-মুচড়ে যায়। এরপর কবজি থেকে হাতটাকে কেটে ফেলতে হ</span><span style=\"font-size: 1rem;\">তখন তিনি পঞ্চম শ্রেণির ছাত্র। একদিন স্কুল থেকে বাড়িতে ফেরার পথে দ্রুতগামী ট্রাক ধাক্কা দিয়ে তাঁকে রাস্তার ওপর ফেলে দেয়। ডান হাতটি ভেঙে থেঁতলে-মুচড়ে যায়। এরপর কবজি থেকে হাতটাকে কেটে ফেলতে হ</span><span style=\"font-size: 1rem;\">তখন তিনি পঞ্চম শ্রেণির ছাত্র। একদিন স্কুল থেকে বাড়িতে ফেরার পথে দ্রুতগামী ট্রাক ধাক্কা দিয়ে তাঁকে রাস্তার ওপর ফেলে দেয়। ডান হাতটি ভেঙে থেঁতলে-মুচড়ে যায়। এরপর কবজি থেকে হাতটাকে কেটে ফেলতে হ</span><span style=\"font-size: 1rem;\">তখন তিনি পঞ্চম শ্রেণির ছাত্র। একদিন স্কুল থেকে বাড়িতে ফেরার পথে দ্রুতগামী ট্রাক ধাক্কা দিয়ে তাঁকে রাস্তার ওপর ফেলে দেয়। ডান হাতটি ভেঙে থেঁতলে-মুচড়ে যায়। এরপর কবজি থেকে হাতটাকে কেটে ফেলতে হ</span><span style=\"font-size: 1rem;\">তখন তিনি পঞ্চম শ্রেণির ছাত্র। একদিন স্কুল থেকে বাড়িতে ফেরার পথে দ্রুতগামী ট্রাক ধাক্কা দিয়ে তাঁকে রাস্তার ওপর ফেলে দেয়। ডান হাতটি ভেঙে থেঁতলে-মুচড়ে যায়। এরপর কবজি থেকে হাতটাকে কেটে ফেলতে হ</span><span style=\"font-size: 1rem;\">তখন তিনি পঞ্চম শ্রেণির ছাত্র। একদিন স্কুল থেকে বাড়িতে ফেরার পথে দ্রুতগামী ট্রাক ধাক্কা দিয়ে তাঁকে রাস্তার ওপর ফেলে দেয়। ডান হাতটি ভেঙে থেঁতলে-মুচড়ে যায়। এরপর কবজি থেকে হাতটাকে কেটে ফেলতে হ</span><span style=\"font-size: 1rem;\"