(56, 1113, 5, 6, 1, 1, 1, 'সিলেটে সড়কে গুঁড়ি ফেলে, আগুন জ্বালিয়ে অবরোধ, স্বেচ্ছাসেবক দলের নেতা আটক', NULL, NULL, 'public/postimages/65509f747df87.png', 'বিএনপির ডাকা চতুর্থ দফা অবরোধের প্রথম দিন আজ রোববার সকালে সিলেটে সড়কে গাছের গুঁড়ি ফেলে, আগুন জ্বালিয়ে যানবাহন চলাচলে প্রতিবন্ধকতা তৈরি করা হয়েছে। অবরোধের সমর্থনে বিক্ষোভ মিছিল ও পিকেটিংয়ের সময় এক স্বেচ্ছাসেবক দলের নেতাকে আটক করেছে পুলিশ। আটক মামুনুর রশীদ সিলেট মহানগর ১৭ নম্বর ওয়ার্ড স্বেচ্ছাসেবক দলের আহ্বায়ক।', '<p>বিএনপির ডাকা চতুর্থ দফা অবরোধের প্রথম দিন আজ রোববার সকালে সিলেটে সড়কে গাছের গুঁড়ি ফেলে, আগুন জ্বালিয়ে যানবাহন চলাচলে প্রতিবন্ধকতা তৈরি করা হয়েছে। অবরোধের সমর্থনে বিক্ষোভ মিছিল ও পিকেটিংয়ের', 'dhaka', NULL, 1, 1, 1, 1, '08-11-2023', 'November', NULL, NULL, NULL, NULL, NULL, '56/সিলেটে-সড়কে-গুঁড়ি-ফেলে,-আগুন-জ্বালিয়ে-অবরোধ,-স্বেচ্ছাসেবক-দলের-নেতা-আটক'),
(57, 1113, 2, 4, 1, 1, 1, 'বায়ুদূষণে আজ ঢাকা বিশ্বে পঞ্চম', NULL, NULL, 'public/postimages/655088a1966ce.png', 'বিশ্বের ১০০টি দেশের মধ্যে আজ রোববার সকাল সাড়ে আটটার দিকে বায়ুদূষণে ঢাকার অবস্থান পঞ্চম। আইকিউএয়ারের বাতাসের মানসূচকে (এয়ার কোয়ালিটি ইনডেক্স-একিউআই) এ সময় ঢাকার স্কোর ছিল ১৮৭। বাতাসের এ মান ‘অস্বাস্থ্যকর’ হিসেবে বিবেচনা করা হয়। গতকাল শনিবার বায়ুদূষণে ঢাকার অবস্থান ছিল দ্বিতীয়, আর স্কোর ছিল ২০৮।', '<p>বিশ্বের ১০০টি দেশের মধ্যে আজ রোববার সকাল সাড়ে আটটার দিকে বায়ুদূষণে ঢাকার অবস্থান পঞ্চম। আইকিউএয়ারের বাতাসের মানসূচকে (এয়ার কোয়ালিটি ইনডেক্স-একিউআই) এ সময় ঢাকার স্কোর ছিল ১৮৭। বাতাসের এ মান', 'dhaka', NULL, 1, 1, 1, 1, '08-11-2023', 'November', NULL, NULL, NULL, NULL, NULL, '57/বায়ুদূষণে-আজ-ঢাকা-বিশ্বে-পঞ্চম'),
(59, 1113, 2, 3, 1, 1, 1, 'মৌলভীবাজারে হাওর এলাকার পথে-হাটে বেচাকেনা হচ্ছে বিপন্ন পাখি', NULL, NULL, 'public/postimages/6550899675380.png', 'এখনো শীত খুব একটা নামেনি। হাওরে পরিযায়ী পাখিদের আসা শুরু হয়নি। তবু দলছুটের মতো যে পাখিরা আসছে, সেই চেনা-অচেনা, বিপন্ন এবং স্থানীয় আবাসিক পাখিরা শিকারির জালে ধরা পড়ছে। হাওরপারের পথে ও হাটে এই পাখিদের প্রকাশ্যে বেচাকেনা চলছে।', '<p>এখনো শীত খুব একটা নামেনি। হাওরে পরিযায়ী পাখিদের আসা শুরু হয়নি। তবু দলছুটের মতো যে পাখিরা আসছে, সেই চেনা-অচেনা, বিপন্ন এবং স্থানীয় আবাসিক পাখিরা শিকারির জালে ধরা পড়ছে। হাওরপারের পথে ও হাটে', 'dhaka', NULL, 1, NULL, NULL, NULL, '09-11-2023', 'November', NULL, NULL, NULL, 1, NULL, '59/মৌলভীবাজারে-হাওর-এলাকার-পথে-হাটে-বেচাকেনা-হচ্ছে-বিপন্ন-পাখি'),
