(65, 1113, 6, 27, 1, 1, 1, 'লন্ডনে ফিলিস্তিনের পক্ষে বিক্ষোভ ঠেকাতে পাল্টা বিক্ষোভ, আটক ৮২', NULL, NULL, 'public/postimages/6550766bc3fc1.png', 'ফিলিস্তিনের গাজায় ইসরায়েলের নির্বিচার হামলার প্রতিবাদে যুক্তরাজ্যের রাজধানী লন্ডনে বড় এক বিক্ষোভ হয়েছে। গতকাল শনিবারের এই বিক্ষোভে তিন লাখের বেশি মানুষ অংশ নেন। এই বিক্ষোভ প্রতিহত করতে পাল্টা বিক্ষোভে নামা ৮২ জনকে আটক করেছে লন্ডনের পুলিশ।', '<p>ফিলিস্তিনের গাজায় ইসরায়েলের নির্বিচার হামলার প্রতিবাদে যুক্তরাজ্যের রাজধানী লন্ডনে বড় এক বিক্ষোভ হয়েছে। গতকাল শনিবারের এই বিক্ষোভে তিন লাখের বেশি মানুষ অংশ নেন। এই বিক্ষোভ প্রতিহত করতে পাল', 'gaza', NULL, 1, 1, 1, 1, '09-11-2023', 'November', NULL, NULL, NULL, 1, NULL, '65/লন্ডনে-ফিলিস্তিনের-পক্ষে-বিক্ষোভ-ঠেকাতে-পাল্টা-বিক্ষোভ,-আটক-৮২'),
(66, 1113, 6, 27, 1, 1, 1, 'যেভাবে মাংসখেকো পাখি দিয়ে লাশ খুঁজছে ইসরায়েল', NULL, NULL, 'public/postimages/655076d8a184d.png', 'ফিলিস্তিনের স্বাধীনতা আন্দোলনের সশস্ত্র গোষ্ঠী হামাসের হামলায় গত ৭ অক্টোবর ইসরায়েলে বহু মানুষের মৃত্যু হয়। তাঁদের অনেকের মরদেহ খুঁজে বের করতে বিশেষ এক পদ্ধতি হাতে নিয়েছে ইসরায়েল। দেশটির একজন বন্য প্রাণিবিশেষজ্ঞ বলেছেন, মরদেহগুলো খুঁজতে মাংসখেকো পাখি ব্যবহার করা হচ্ছে।', '<p>ফিলিস্তিনের স্বাধীনতা আন্দোলনের সশস্ত্র গোষ্ঠী হামাসের হামলায় গত ৭ অক্টোবর ইসরায়েলে বহু মানুষের মৃত্যু হয়। তাঁদের অনেকের মরদেহ খুঁজে বের করতে বিশেষ এক পদ্ধতি হাতে নিয়েছে ইসরায়েল। দেশটির এক', 'nbbvvn', NULL, 1, 1, 1, 1, '09-11-2023', 'November', NULL, NULL, NULL, 1, NULL, '66/যেভাবে-মাংসখেকো-পাখি-দিয়ে-লাশ-খুঁজছে-ইসরায়েল'),
(67, 1113, 6, 27, 1, 1, 1, 'যুক্তরাষ্ট্রে প্রথমবার পুরো চোখ প্রতিস্থাপন', NULL, NULL, 'public/postimages/655077463cc3e.png', 'প্রথমবারের মতো পুরো চোখ প্রতিস্থাপনে সফল হয়েছে যুক্তরাষ্ট্রের নিউইয়র্কের একদল চিকিৎসক। চিকিৎসাজগতে এটিকে অনন্য একটি অর্জন হিসেবে বিবেচনা করা হচ্ছে। তবে প্রতিস্থাপনের পর ওই রোগী চোখে দেখতে', '<p>প্রথমবারের মতো পুরো চোখ প্রতিস্থাপনে সফল হয়েছে যুক্তরাষ্ট্রের নিউইয়র্কের একদল চিকিৎসক। চিকিৎসাজগতে এটিকে অনন্য একটি অর্জন হিসেবে বিবেচনা করা হচ্ছে। তবে প্রতিস্থাপনের পর ওই রোগী চোখে দেখতে<span style=\"font-size: 1rem;\">প্রথমবারের মতো পুরো চোখ প্রতিস্থাপনে সফল হয়েছে যুক্তরাষ্ট্রের নিউইয়র্কের একদল চিকিৎসক। চিকিৎসাজগতে এটিকে অনন্য একটি অর্জন হিসেবে বিবেচনা করা হচ্ছে। তবে প্রতিস্থাপনের পর ওই রোগী চোখে দেখতে</span><span style=\"font-size: 1rem;\">প্রথমবারের মতো পুরো চোখ প্রতিস্থাপনে সফল হয়েছে যুক্তরাষ্ট্রের নিউইয়র্কের একদল চিকিৎসক। চিকিৎসাজগতে এটিকে অনন্য একটি অর্জন হিসেবে বিবেচনা করা হচ্ছে। তবে প্রতিস্থাপনের পর ওই রোগী চোখে দেখতে</span><span style=\"font-size: 1rem;\">প্রথমবারের মতো পুরো চোখ প্রতিস্থাপনে সফল হয়েছে যুক্তরাষ্ট্রের নিউইয়র্কের একদল চিকিৎসক। চিকিৎসাজগতে এটিকে অনন্য একটি অর্জন হিসেবে বিবেচনা করা হচ্ছে। তবে প্রতিস্থাপনের পর ওই রোগী চোখে দেখতে</span><span style=\"font-size: 1rem;\">প্রথমবারের মতো পুরো চোখ প্রতিস্থাপনে সফল হয়েছে যুক্তরাষ্ট্রের নিউইয়র্কের একদল চিকিৎসক। চিকিৎসাজগতে এটিকে অনন্য একটি অর্জন হিসেবে বিবেচনা করা হচ্ছে। তবে প্রতিস্থাপনের পর ওই রোগী চোখে দেখতে</span><span style=\"font-size: 1rem;\">প্রথমবারের মতো পুরো চোখ প্রতিস্থাপনে সফল হয়েছে যুক্তরাষ্ট্রের নিউইয়র্কের একদল চিকিৎসক। চিকিৎসাজগতে এটিকে অনন্য একটি অর্জন হিসেবে বিবেচনা করা হচ্ছে। তবে প্রতিস্থাপনের পর ওই রোগী চোখে দেখতে</span><span style=\"font-size: 1rem;\">প্রথমবারের মতো পুরো চোখ প্রতিস্থাপনে সফল হয়েছে যুক্তরাষ্ট্রের নিউইয়র্কের একদল চিকিৎসক। চিকিৎসাজগতে এটিকে অনন্য একটি অর্জন হিসেবে বিবেচনা করা হচ্ছে। তবে প্রতিস্থাপনের পর ওই রোগী চোখে দেখতে</span><span style=\"font-size: 1rem;\">প্রথমবারের মতো পুরো চোখ প্রতিস্থাপনে সফল হয়েছে যুক্তরাষ্ট্রের নিউইয়র্কের একদল চিকিৎসক। চিকিৎসাজগতে