(68, 1113, 7, 9, 1, 1, 1, 'দেশে ফিরেছে বাংলাদেশ দল, কোচদের মধ্যে এসেছেন শুধু হাথুরুসিংহে', NULL, NULL, 'public/postimages/6550815455e13.png', 'বাংলাদেশ দল গতকালই বিশ্বকাপের প্রথম পর্বে তাদের শেষ ম্যাচটি খেলেছে। অস্ট্রেলিয়ার বিপক্ষে পুনেতে ৮ উইকেটে হেরেছে বাংলাদেশ দল। এ নিয়ে লিগ পর্বের ৯টি ম্যাচ খেলে বাংলাদেশ জিতেছে মাত্র ২টিতে। বিশ্বকাপের ব্যর্থ মিশন শেষে বাংলাদেশ দল আজ সকালে পৌনে ১০টায় ঢাকায় পৌঁছেছে।', '<p>বাংলাদেশ দল গতকালই বিশ্বকাপের প্রথম পর্বে তাদের শেষ ম্যাচটি খেলেছে। অস্ট্রেলিয়ার বিপক্ষে পুনেতে ৮ উইকেটে হেরেছে বাংলাদেশ দল। এ নিয়ে লিগ পর্বের ৯টি ম্যাচ খেলে বাংলাদেশ জিতেছে মাত্র ২টিতে। ব', 'sports', NULL, 1, 1, 1, 1, '09-11-2023', 'November', NULL, NULL, NULL, NULL, NULL, '68/দেশে-ফিরেছে-বাংলাদেশ-দল,-কোচদের-মধ্যে-এসেছেন-শুধু-হাথুরুসিংহে'),
(69, 1113, 7, 10, 1, 1, 1, 'কেইনের রেকর্ড, এমবাপ্পের হ্যাটট্রিকেও খুশি নন এনরিকে', NULL, NULL, 'public/postimages/6550825cdbdb2.png', 'লিগ বদলেছে, দল বদলেছে, কিন্তু বদলাননি হ্যারি কেইন। বদলায়নি তাঁর গোল করার ধারাও। বুন্দেসলিগায় হেইডেনহেইমের বিপক্ষে এবার জোড়া গোল করলেন কেইন। তাঁর জোড়া গোলে বায়ার্ন জিতেছে ৪-২ ব্যবধানে। এই জয়ে বুন্দেসলিগার পয়েন্ট তালিকার শীর্ষে উঠেছে বায়ার্ন এবং এর মধ্য দিয়ে কেইন ভাঙলেন বুন্দেসলিগার গোলের একটি রেকর্ডও।', '<p>লিগ বদলেছে, দল বদলেছে, কিন্তু বদলাননি হ্যারি কেইন। বদলায়নি তাঁর গোল করার ধারাও। বুন্দেসলিগায় হেইডেনহেইমের বিপক্ষে এবার জোড়া গোল করলেন কেইন। তাঁর জোড়া গোলে বায়ার্ন জিতেছে ৪-২ ব্যবধানে। এই জ', 'nbbvvn', NULL, NULL, NULL, NULL, NULL, '09-11-2023', 'November', NULL, NULL, NULL, 1, NULL, '69/কেইনের-রেকর্ড,-এমবাপ্পের-হ্যাটট্রিকেও-খুশি-নন-এনরিকে'),
(70, 1112, 7, 10, 1, 1, 1, 'সংবাদ সম্মেলনে আর্থার, ‘বাবরকে বেড়ে ওঠার সুযোগ দিতে হবে’', NULL, NULL, 'public/postimages/6550839b1e4a0.png', 'পাকিস্তানের বিশ্বকাপ শেষ। ইংল্যান্ডের কাছে হেরে পাকিস্তান বিশ্বকাপ শেষ করেছে পয়েন্ট তালিকার পাঁচ নম্বরে থেকে। বিশ্বকাপ শেষে পাকিস্তান ক্রিকেটের সবচেয়ে বড় প্রশ্ন হচ্ছে, বাবর আজম কি অধিনায়ক হিসেবে থাকছেন?', '<p>পাকিস্তানের বিশ্বকাপ শেষ। ইংল্যান্ডের কাছে হেরে পাকিস্তান বিশ্বকাপ শেষ করেছে পয়েন্ট তালিকার পাঁচ নম্বরে থেকে। বিশ্বকাপ শেষে পাকিস্তান ক্রিকেটের সবচেয়ে বড় প্রশ্ন হচ্ছে, বাবর আজম কি অধিনায়ক', 'cricket', NULL, NULL, NULL, NULL, NULL, '09-11-2023', 'November', NULL, NULL, NULL, 1, NULL, '70/সংবাদ-সম্মেলনে-আর্থার,-‘বাবরকে-বেড়ে-ওঠার-সুযোগ-দিতে-হবে’'),
(71, 1113, 7, 9, 1, 1, 1, '‘মৌসুমের সেরা ম্যাচে’ ভ্যালেন্সিয়ার জালে রিয়ালের ৫ গোল', NULL, NULL, 'public/postimages/65508413a9904.png', 'লা লিগায় আগের ম্যাচে রায়ো ভায়েকানোর সঙ্গে গোলশূন্য ড্র করায় একটু চাপেই ছিল রিয়াল মাদ্রিদ। ভ্যালেন্সিয়ার বিপক্ষেও পয়েন্ট হারালে শীর্ষে থাকা জিরোনার সঙ্গে ব্যবধান আরও বেড়ে যেত। তবে আগের ম্যাচে ড্রয়ের ধাক্কা সামলে দারুণভাবে ঘুরে দাঁড়িয়েছে রিয়াল। ভ্যালেন্সিয়াকে ৫-১ গোলে উড়িয়ে দিয়েছে তারা।', '<p>লা লিগায় আগের ম্যাচে রায়ো ভায়েকানোর সঙ্গে গোলশূন্য ড্র করায় একটু চাপেই ছিল রিয়াল মাদ্রিদ। ভ্যালেন্সিয়ার বিপক্ষেও পয়েন্ট হারালে শীর্ষে থাকা জিরোনার সঙ্গে ব্যবধান আরও বেড়ে যেত। তবে আগের ম্যা', 'cric', NULL, NULL, NULL, NULL, NULL, '09-11-2023', 'November', NULL, NULL, NULL, 1, NULL, '71/‘মৌসুমের-সেরা-ম্যাচে’-ভ্যালেন্সিয়ার-জালে-রিয়ালের-৫-গোল'),
(80, 1113, 8, 12, 1, 1, 1, 'অনেক কাছের বন্ধু আমাকে হাসপাতালে দেখতেও যায়নি...', NULL, NULL, 'public/postimages/65509a6c262ef.png', 'গল্পটা হুমায়ূন আহমেদের জীবন থেকে প্রেরণা নিয়ে লেখা। এক তরুণ বিদেশ থেকে পড়াশোনা করে দেশে ফিরে হুমায়ূন আহমেদের মতো লেখক হতে চায়। এরপর ‘দরিদ্রতার স্বাদ’ নিয়ে সে এক ভাড়া বাসায় ওঠে। সেখানে এক তরুণী তাকে পছন্দ করে। এরপর নানা ঘটনা ঘটতে থাকে।', '<p>গল্পটা হুমায়ূন আহমেদের জীবন থেকে প্রেরণা নিয়ে লেখা। এক তরুণ বিদেশ থেকে পড়াশোনা করে দেশে ফিরে হুমায়ূন আহমেদের মতো লেখক হতে চায়। এরপর ‘দরিদ্রতার স্বাদ’ নিয়ে সে এক ভাড়া বাসায় ওঠে। সেখানে এক ত', 'nbbvvn', NULL, NULL, NULL, NULL, NULL, '10-11-2023', 'November', NULL, NULL, NULL, 1, NULL, '80/অনেক-কাছের-বন্ধু-আমাকে-হাসপাতালে-দেখতেও-যায়নি...'),
(81, 1113, 8, 13, 1, 1, 1, 'টুটুলের সঙ্গে বিচ্ছেদের পর তানিয়া বললেন, সন্তানের পিতাকে তো কখনোই ছোট করব না', NULL, NULL, 'public/postimages/65509adc13a7f.png', 'দুই দিন পরপর পরিচালকের সঙ্গে কথা হচ্ছে। সাইন করতে চেয়েছিল। কিন্তু যুক্তরাষ্ট্রে চলে এসেছি। সাধারণত আমাদের এখানে দেখা যায়, হিরো-হিরোইননির্ভর গল্প। এটা প্যারালাল দুই নারীর গল্প। তারপর একটা রেখায় গিয়ে মিলেছে।', '<p>দুই দিন পরপর পরিচালকের সঙ্গে কথা হচ্ছে। সাইন করতে চেয়েছিল। কিন্তু যুক্তরাষ্ট্রে চলে এসেছি। সাধারণত আমাদের এখানে দেখা যায়, হিরো-হিরোইননির্ভর গল্প। এটা প্যারালাল দুই নারীর গল্প। তারপর একটা র', 'dhaka', NULL, NULL, NULL, NULL, NULL, '10-11-2023', 'November', NULL, NULL, NULL, 1, NULL, '81/টুটুলের-সঙ্গে-বিচ্ছেদের-পর-তানিয়া-বললেন,-সন্তানের-পিতাকে-তো-কখনোই-ছোট-করব-না'),
