(85, 1112, 5, 6, 1, 1, 1, 'অগ্নিসন্ত্রাসের শিকার হচ্ছে সাধারণ জনগণ: প্রধানমন্ত্রী', NULL, NULL, 'public/postimages/6550ac00ee17a.png', 'আন্দোলনের নামে আবার শুরু হওয়া অগ্নিসন্ত্রাসের শিকার সাধারণ মানুষ হচ্ছেন বলে মন্তব্য করেছেন প্রধানমন্ত্রী শেখ হাসিনা। তিনি বলেছেন, ‘আমি জানি না, এসব থেকে কে কতটা লাভবান হয়। তবে কিছু লোক, বিশেষ করে সাধারণ মানুষ এসব ঘটনার শিকার হচ্ছেন।’', '<p>আন্দোলনের নামে আবার শুরু হওয়া অগ্নিসন্ত্রাসের শিকার সাধারণ মানুষ হচ্ছেন বলে মন্তব্য করেছেন প্রধানমন্ত্রী শেখ হাসিনা। তিনি বলেছেন, ‘আমি জানি না, এসব থেকে কে কতটা লাভবান হয়। তবে কিছু লোক, বি', 'dhaka', NULL, 1, NULL, NULL, NULL, '10-11-2023', 'November', NULL, NULL, NULL, 1, NULL, '85/অগ্নিসন্ত্রাসের-শিকার-হচ্ছে-সাধারণ-জনগণ:-প্রধানমন্ত্রী'),
(86, 1113, 9, 30, 1, 1, 1, 'উনি সবকিছু এমন ষড়যন্ত্র বইলা চালায়ে যাইতে চান ক্যান, ফেসবুকে পরীমনি', NULL, NULL, 'public/postimages/6550993728c4f.png', 'সম্প্রতি সহকর্মীদের সঙ্গে আনন্দ আড্ডায় যোগ দিয়েছিলেন মিশা সওদাগর।', '<p>সম্প্রতি সহকর্মীদের সঙ্গে আনন্দ আড্ডায় যোগ দিয়েছিলেন মিশা সওদাগর। তিনি ছবিটি পোস্ট করে লিখেছেন, ‘শিল্পী তোমাকে অনেক অনেক হৃদয় নিংড়ানো শুভেচ্ছা ভালোবাসা। কালকে তুমি আমাদের সবাইকে একসঙ্গে কর', 'dhaka', NULL, NULL, NULL, NULL, NULL, '10-11-2023', 'November', NULL, NULL, NULL, 1, NULL, '86/উনি-সবকিছু-এমন-ষড়যন্ত্র-বইলা-চালায়ে-যাইতে-চান-ক্যান,-ফেসবুকে-পরীমনি'),
(87, 1113, 9, 30, 1, 1, 1, 'বিজ্ঞানী আইনস্টাইনের জন্য নভেম্বর কেন গুরুত্বপূর্ণ', NULL, NULL, 'public/postimages/655099b6141ba.png', 'বিজ্ঞানের ইতিহাসে নভেম্বরকে বেশ গুরুত্বপূর্ণ একটি মাস ধরা হয়। ১৯১৯ সালের নভেম্বর মাসে দারুণ এক ঘটনা পুরো বিজ্ঞানের ইতিহাসে নতুন বাঁক তৈরি করেছিল। ১৯১৯ সাল যখন শুরু হয়, তখন আলবার্ট আইনস্টাইন নামটি তেমন আলোচিত ছিল না। পদার্থবিজ্ঞানীদের আলাপ বা আড্ডার বাইরে অজানা ছিল এই নাম।', '<p>বিজ্ঞানের ইতিহাসে নভেম্বরকে বেশ গুরুত্বপূর্ণ একটি মাস ধরা হয়। ১৯১৯ সালের নভেম্বর মাসে দারুণ এক ঘটনা পুরো বিজ্ঞানের ইতিহাসে নতুন বাঁক তৈরি করেছিল। ১৯১৯ সাল যখন শুরু হয়, তখন আলবার্ট আইনস্টাই', 'dhaka', NULL, NULL, NULL, NULL, NULL, '10-11-2023', 'November', NULL, NULL, NULL, 1, NULL, '87/বিজ্ঞানী-আইনস্টাইনের-জন্য-নভেম্বর-কেন-গুরুত্বপূর্ণ'),
