(91, 1113, 10, 33, 1, 1, 1, 'ঢাকায় পুলিশের গাড়িতে আগুনের ঘটনায় দুজন গ্রেপ্তার', '', NULL, 'public/postimages/654d9e88775bd.jpg', 'এই সব কী! রোজ বাসে আগুন দিচ্ছেন কেন? কখনো কখনো যাত্রীদের নামিয়ে দিয়ে, কখনো-বা ভেতরে ঘুমন্ত বাসের চালক বা সহকারীকে রেখে রোজ বাসে আগুন দেওয়ার মানে কী! কী অর্জন করতে চাইছেন এসব থেকে!', '<p>hjgggggggggggggggggggg</p>', 'nbbvvn', NULL, NULL, NULL, NULL, NULL, '10-11-2023', 'November', NULL, NULL, NULL, 1, NULL, NULL),
(96, 1113, 2, 3, 1, 1, 1, 'কাশ্মীরে হাউস বোটে আগুন, বাংলাদেশি ৩ পর্যটকের মৃত্যু', NULL, NULL, 'public/postimages/655089dfc5959.png', 'কাশ্মীর পুলিশ জানিয়েছে, গতকাল শনিবার ভোররাতে ডাল লেকে নোঙ্গর করে রাখা একটি হাউস বোটে আগুন লাগে। এরপর সে আগুন আশপাশে থাকা আরও কয়েকটি বোটে ছড়িয়ে পড়ে।', '<p>কাশ্মীর পুলিশ জানিয়েছে, গতকাল শনিবার ভোররাতে ডাল লেকে নোঙ্গর করে রাখা একটি হাউস বোটে আগুন লাগে। এরপর সে আগুন আশপাশে থাকা আরও কয়েকটি বোটে ছড়িয়ে পড়ে।<br></p><p><span style=\"font-size: 1rem;\"', 'dhaka', NULL, 1, 1, 1, 1, '10-11-2023', 'November', NULL, NULL, NULL, 1, NULL, '96/কাশ্মীরে-হাউস-বোটে-আগুন,-বাংলাদেশি-৩-পর্যটকের-মৃত্যু'),
