(106, 1113, 13, 16, 1, 1, 1, 'হজের নিবন্ধন শুরু ১৫ নভেম্বর', NULL, NULL, 'public/postimages/655078f85a581.jpg', '২০২৪ সালের হজের নিবন্ধন বিজ্ঞপ্তিতে এ তথ্য জানিয়েছে ধর্ম বিষয়ক মন্ত্রণালয়। এতে বলা হয়, সরকারি ও বেসরকারি ব্যবস্থাপনার (হজ এজেন্সি) হজযাত্রীরা ১৫ নভেম্বর থেকে নিবন্ধনের টাকা জমা দিতে পারবেন। নিবন্ধনের টাকা জমা নেওয়া হবে ১০ ডিসেম্বর পর্যন্ত।', '<p>২০২৪ সালের হজের নিবন্ধন বিজ্ঞপ্তিতে এ তথ্য জানিয়েছে ধর্ম বিষয়ক মন্ত্রণালয়। এতে বলা হয়, সরকারি ও বেসরকারি ব্যবস্থাপনার (হজ এজেন্সি) হজযাত্রীরা ১৫ নভেম্বর থেকে নিবন্ধনের টাকা জমা দিতে পারবেন', 'hajj', NULL, NULL, NULL, NULL, NULL, '10-11-2023', 'November', NULL, NULL, NULL, 1, NULL, '106/হজের-নিবন্ধন-শুরু-১৫-নভেম্বর'),
(107, 1113, 13, 17, 1, 1, 1, 'নোয়াখালীতে ফসলের মাঠে বাদামি গাছফড়িংয়ের উপদ্রব, পাকার আগেই ধান কাটছেন কৃষকেরা', NULL, NULL, 'public/postimages/655079e6c79ec.png', 'নোয়াখালীর শস্যভান্ডার খ্যাত সুবর্ণচর উপজেলায় আমন ধানের খেতে বেড়েছে বাদামি গাছফড়িংয়ের উপদ্রব। ধান পাকার মুহূর্তে এই পোকার উপদ্রবে নষ্ট হচ্ছে খেত। এতে দুশ্চিন্তায় পড়েছেন চাষিরা। এ অবস্থায় কৃষকদের কেউ কেউ পুরোপুরি পাকার আগেই কেটে ফেলছেন ধান, কেউ আবার কীটনাশক ছিটিয়ে ফসল রক্ষার চেষ্টা করছেন।', '<p>নোয়াখালীর শস্যভান্ডার খ্যাত সুবর্ণচর উপজেলায় আমন ধানের খেতে বেড়েছে বাদামি গাছফড়িংয়ের উপদ্রব। ধান পাকার মুহূর্তে এই পোকার উপদ্রবে নষ্ট হচ্ছে খেত। এতে দুশ্চিন্তায় পড়েছেন চাষিরা। এ অবস্থায় কৃ', 'agriculture', NULL, NULL, NULL, NULL, NULL, '10-11-2023', 'November', NULL, NULL, NULL, 1, NULL, '107/নোয়াখালীতে-ফসলের-মাঠে-বাদামি-গাছফড়িংয়ের-উপদ্রব,-পাকার-আগেই-ধান-কাটছেন-কৃষকেরা'),
(108, 1113, 13, 16, 1, 1, 1, 'সুরা ইখলাসের শিক্ষা', NULL, NULL, 'public/postimages/65507a9619889.png', 'সুরা ইখলাস পবিত্র কোরআনের ১১২তম সুরা। এটি মক্কায় অবতীর্ণ হয়েছে। এর রুকু ১, আয়াত ৪। এই সুরায় তওহিদ বা আল্লাহর একত্ববাদের ঘোষণার পর আল্লাহর সন্তানসন্ততি আছে বলে যে ভ্রান্ত ধারণা করা হয়, তার প্রতিবাদ করা হয়েছে। আল্লাহ সব অভাবের অতীত এবং তাঁর কোনো তুলনা নেই।', '<p>সুরা ইখলাস পবিত্র কোরআনের ১১২তম সুরা। এটি মক্কায় অবতীর্ণ হয়েছে। এর রুকু ১, আয়াত ৪। এই সুরায় তওহিদ বা আল্লাহর একত্ববাদের ঘোষণার পর আল্লাহর সন্তানসন্ততি আছে বলে যে ভ্রান্ত ধারণা করা হয়, তা', 'islam', NULL, NULL, NULL, NULL, NULL, '10-11-2023', 'November', NULL, NULL, NULL, 1, NULL, '108/সুরা-ইখলাসের-শিক্ষা'),
(109, 1113, 13, 16, 1, 1, 1, 'খিজির (আ.)–এর সঙ্গী ‎মুসা (আ.)', NULL, NULL, 'public/postimages/65507b1f1a641.png', 'হজরত উবাই ইবনে কাব (রা.)-র বরাতে এই হাদিসটির বর্ণনা আছে। তিনি নবী (সা.)-এর কাছে নিচের ঘটনাটি শুনেছেন।', '<p>হজরত উবাই ইবনে কাব (রা.)-র বরাতে এই হাদিসটির বর্ণনা আছে। তিনি নবী (সা.)-এর কাছে নিচের ঘটনাটি শুনেছেন।<span style=\"font-size: 1rem;\">একবার মুসা (আ.) বনি ইসরাইলের এক সমাবেশে ভাষণ দেওয়ার জন্য', 'islam', NULL, NULL, NULL, NULL, NULL, '10-11-2023', 'November', NULL, NULL, NULL, 1, NULL, '70/সংবাদ-সম্মেলনে-আর্থার,-‘বাবরকে-বেড়ে-ওঠার-সুযোগ-দিতে-হবে’'),
(113, 1113, 2, 3, NULL, NULL, 1, 'ঢাকায় পুলিশের গাড়িতে আগুনের ঘটনায় দুজন গ্রেপ্তার', NULL, NULL, 'public/postimages/655320281b0f4.jpg', 'এই সব কী! রোজ বাসে আগুন দিচ্ছেন কেন? কখনো কখনো যাত্রীদের নামিয়ে দিয়ে, কখনো-বা ভেতরে ঘুমন্ত বাসের চালক বা সহকারীকে রেখে রোজ বাসে আগুন দেওয়ার মানে কী! কী অর্জন করতে চাইছেন এসব থেকে!', '<p>এই সব কী! রোজ বাসে আগুন দিচ্ছেন কেন? কখনো কখনো যাত্রীদের নামিয়ে দিয়ে, কখনো-বা ভেতরে ঘুমন্ত বাসের চালক বা সহকারীকে রেখে রোজ বাসে আগুন দেওয়ার মানে কী! কী অর্জন করতে চাইছেন এসব থেকে!<br>', 'nbbvvn', NULL, 1, 1, 1, 1, '14-11-2023', 'November', NULL, NULL, NULL, 1, NULL, '113/ঢাকায়-পুলিশের-গাড়িতে-আগুনের-ঘটনায়-দুজন-গ্রেপ্তার'),
(114, 1099, 10, 39, NULL, NULL, 1, 'দেয়ালঘেরা বাড়িটিতে তিন খুন নিয়ে নানা জল্পনা', NULL, NULL, 'public/postimages/65bcf21f736a8.jpg', 'গলা কাটা রক্তাক্ত অবস্থায় বাড়ির বাইরে এসে ঢলে পড়েন আশিকুল হক মোল্লা (৪০)। তৎক্ষণাৎ স্থানীয় লোকজন এগিয়ে তাঁকে উদ্ধার করে হাসপাতালে নেন। পরে বাড়ির শয়নকক্ষে একটি বিছানায় তাঁর স্ত্রী তহুরা বেগম (৩০), দুই শিশুকন্যা আয়েশা আক্তার (১১) ও যারিনের (৬) লাশ পড়ে থাকতে দেখা যায়। তবে তিনটি লাশের শরীরেই রক্ত বা কোনো জখমের চিহ্ন নেই।', '<p>গলা কাটা রক্তাক্ত অবস্থায় বাড়ির বাইরে এসে ঢলে পড়েন আশিকুল হক মোল্লা (৪০)। তৎক্ষণাৎ স্থানীয় লোকজন এগিয়ে তাঁকে উদ্ধার করে হাসপাতালে নেন। পরে বাড়ির শয়নকক্ষে একটি বিছানায় তাঁর স্ত্রী তহুরা বেগম (৩০), দুই শিশুকন্যা আয়েশা আক্তার (১১) ও যারিনের (৬) লাশ পড়ে থাকতে দেখা যায়। তবে তিনটি লাশের শরীরেই রক্ত বা কোনো জখমের চিহ্ন নেই।</p><p><span style=\"font-size: 1rem;\">ঘটনাটিকে রহস্যজনক বলছে পুলিশ। আত্মীয়স্বজন ও প্রতিবেশীদের কেউই ঘটনা সম্পর্কে সুস্পষ্ট কোনো ধারণা দিতে পারছেন না। আশিকুল হক তাঁর স্ত্রী ও দুই মেয়েকে হত্যা করে আত্মহত্যার চেষ্টা করেছেন, নাকি অন্য কেউ তাঁদের হত্যা করেছে, তা নিয়ে চলছে জল্পনা। নিহত তিনজনের শরীরে জখমের চিহ্ন না থাকায় তাঁদের শ্বাসরোধে নাকি অন্য কোনোভাবে হত্যা করা হয়েছে, সেটিও নিশ্চিত নয়। আবার একই বিছানায় লাশ তিনটি পাশাপাশি রাখা নিয়ে পুরো হত্যাপ্রক্রিয়া নিয়ে তৈরি হয়েছে ধোঁয়াশা।</span><br></p>', 'দেয়ালঘেরা বাড়িটিতে তিন খুন নিয়ে নানা জল্পনা', NULL, 1, 1, 1, 1, '02-02-2024', 'February', NULL, NULL, NULL, 1, NULL, '114/দেয়ালঘেরা-বাড়িটিতে-তিন-খুন-নিয়ে-নানা-জল্পনা'),
(115, 1098, 10, 40, NULL, NULL, 1, 'ট্রান্সজেন্ডার নারীকে নৃশংসভাবে হত্যায় বিচারের', NULL, NULL, 'public/postimages/65bcf2f026e73.png', 'যুক্তরাজ্যে ট্রান্সজেন্ডার এক নারীকে হত্যা করায় ১৬ বছর বয়সী দুজন বিচারের মুখোমুখি হয়েছে। আজ শুক্রবার অভিযুক্ত দুজনের বিচারের রায় হওয়ার কথা রয়েছে।', '<p>যুক্তরাজ্যে ট্রান্সজেন্ডার এক নারীকে হত্যা করায় ১৬ বছর বয়সী দুজন বিচারের মুখোমুখি হয়েছে। আজ শুক্রবার অভিযুক্ত দুজনের বিচারের রায় হওয়ার কথা রয়েছে।</p><p><span style=\"font-size: 1rem;\">ছুরিকাঘাত করে&nbsp; নৃশংস এই হত্যাকাণ্ড ও বিচারের ঘটনা সংবাদমাধ্যমে বেশ আলোচনার জন্ম দিয়েছে।</span><br></p><p><span style=\"font-size: 1rem;\">ঘটনাটি গত বছরের ফেব্রুয়ারির। যুক্তরাজ্যের উত্তর-পশ্চিমাঞ্চলের ওয়ারিংটন নামে একটি শহরে ১৬ বছর বয়সী ট্রান্সজেন্ডার নারী ব্রিয়ান্না ঘেকে হত্যা করা হয়। একটি পার্ক থেকে উদ্ধার করা হয় ব্রিয়ান্নার মরদেহ।</span><br></p><p>মাথা, ঘাড়, বুক আর শরীরের পেছনের অংশে ২৮ বার ছুরিকাঘাত করে ব্রিয়ান্নাকে হত্যা করা হয়েছিল। ওই সময় এই হত্যাকাণ্ড দেশি-বিদেশি সংবাদমাধ্যমে শোরগোল ফেলে দেয়। স্তম্ভিত হন যুক্তরাজ্যবাসী।</p><p><span style=\"font-size: 1rem;\">ব্রিয়ান্নাকে হত্যার অভিযোগ ওঠে ১৫ বছর বয়সী দুজনের বিরুদ্ধে। এই দুজনের বয়স এখন ১৬ বছর। যুক্তরাজ্যে অপ্রাপ্তবয়স্ক অভিযুক্তদের নাম-পরিচয় প্রকাশ করা হয় না। তবে বিচারক সম্মত হওয়ায় আজ রায় ঘোষণার পর দুজনের নাম প্রকাশ করা হবে।</span><br></p><p><br></p>', 'ট্রান্সজেন্ডার নারীকে নৃশংসভাবে হত্যায় বিচারের মুখোমুখি ১৬ বছরের দুজন', NULL, 1, 1, 1, 1, '02-02-2024', 'February', NULL, NULL, NULL, 1, NULL, '115/ট্রান্সজেন্ডার-নারীকে-নৃশংসভাবে-হত্যায়-বিচারের'),
(117, 1077, 10, 41, NULL, NULL, 1, 'নারীর ব্যক্তিগত ভিডিও ছড়িয়ে দেওয়ার ভয় দেখিয়ে চাঁদা দাবি', NULL, NULL, 'public/postimages/65bcf78b1a3bf.png', 'নারীর ব্যক্তিগত ভিডিও চিত্র সামাজিক যোগাযোগমাধ্যমে ছড়িয়ে দেওয়ার ভয় দেখিয়ে দুই লাখ টাকা চাঁদা দাবি এবং অনৈতিক সম্পর্কের প্রস্তাব দেওয়ার অভিযোগে এক তরুণকে গ্রেপ্তার করেছে নোয়াখালী জেলা গোয়েন্দা পুলিশ (ডিবি)। গ্রেপ্তার তরুণের নাম মোশারফ হোসেন ওরফে টিটু (২২)। গতকাল বৃহস্পতিবার সন্ধ্যায় নোয়াখালী সুপারমার্কেট থেকে তাঁকে গ্রেপ্তার করা হয়।', '<p>নারীর ব্যক্তিগত ভিডিও চিত্র সামাজিক যোগাযোগমাধ্যমে ছড়িয়ে দেওয়ার ভয় দেখিয়ে দুই লাখ টাকা চাঁদা দাবি এবং অনৈতিক সম্পর্কের প্রস্তাব দেওয়ার অভিযোগে এক তরুণকে গ্রেপ্তার করেছে নোয়াখালী জেলা গোয়েন্দা পুলিশ (ডিবি)। গ্রেপ্তার তরুণের নাম মোশারফ হোসেন ওরফে টিটু (২২)। গতকাল বৃহস্পতিবার সন্ধ্যায় নোয়াখালী সুপারমার্কেট থেকে তাঁকে গ্রেপ্তার করা হয়।</p><p><br></p><p>পুলিশ জানায়, গ্রেপ্তার মোশারফ হোসেন জেলার কবিরহাট উপজেলার সুন্দলপুর ইউনিয়নের ২ নম্বর ওয়ার্ডের ছবিরপাইক গ্রামের মিয়াধনের ছেলে। তিনি মুঠোফোন মেরামতের কাজ করতেন। গ্রেপ্তারের পর তাঁকে সুধারাম থানায় সোপর্দ করা হয়। সুধারাম থানা-পুলিশ ওই নারীর করা মামলায় তাঁকে গ্রেপ্তার দেখিয়ে আজ শুক্রবার দুপুরে নোয়াখালীর চিফ জুডিশিয়াল ম্যাজিস্ট্রেট আদালতে পাঠায়। আদালত শুনানি শেষে তাঁকে জেলা কারাগারে পাঠান।</p><p>নারীর ব্যক্তিগত ভিডিও চিত্র সামাজিক যোগাযোগমাধ্যমে ছড়িয়ে দেওয়ার ভয় দেখিয়ে দুই লাখ টাকা চাঁদা দাবি এবং অনৈতিক সম্পর্কের প্রস্তাব দেওয়ার অভিযোগে এক তরুণকে গ্রেপ্তার করেছে নোয়াখালী জেলা গোয়েন্দা পুলিশ (ডিবি)। গ্রেপ্তার তরুণের নাম মোশারফ হোসেন ওরফে টিটু (২২)। গতকাল বৃহস্পতিবার সন্ধ্যায় নোয়াখালী সুপারমার্কেট থেকে তাঁকে গ্রেপ্তার করা হয়।</p><p><br></p><p>পুলিশ জানায়, গ্রেপ্তার মোশারফ হোসেন জেলার কবিরহাট উপজেলার সুন্দলপুর ইউনিয়নের ২ নম্বর ওয়ার্ডের ছবিরপাইক গ্রামের মিয়াধনের ছেলে। তিনি মুঠোফোন মেরামতের কাজ করতেন। গ্রেপ্তারের পর তাঁকে সুধারাম থানায় সোপর্দ করা হয়। সুধারাম থানা-পুলিশ ওই নারীর করা মামলায় তাঁকে গ্রেপ্তার দেখিয়ে আজ শুক্রবার দুপুরে নোয়াখালীর চিফ জুডিশিয়াল ম্যাজিস্ট্রেট আদালতে পাঠায়। আদালত শুনানি শেষে তাঁকে জেলা কারাগারে পাঠান।</p><p>নারীর ব্যক্তিগত ভিডিও চিত্র সামাজিক যোগাযোগমাধ্যমে ছড়িয়ে দেওয়ার ভয় দেখিয়ে দুই লাখ টাকা চাঁদা দাবি এবং অনৈতিক সম্পর্কের প্রস্তাব দেওয়ার অভিযোগে এক তরুণকে গ্রেপ্তার করেছে নোয়াখালী জেলা গোয়েন্দা পুলিশ (ডিবি)। গ্রেপ্তার তরুণের নাম মোশারফ হোসেন ওরফে টিটু (২২)। গতকাল বৃহস্পতিবার সন্ধ্যায় নোয়াখালী সুপারমার্কেট থেকে তাঁকে গ্রেপ্তার করা হয়।</p><p><br></p><p>পুলিশ জানায়, গ্রেপ্তার মোশারফ হোসেন জেলার কবিরহাট উপজেলার সুন্দলপুর ইউনিয়নের ২ নম্বর ওয়ার্ডের ছবিরপাইক গ্রামের মিয়াধনের ছেলে। তিনি মুঠোফোন মেরামতের কাজ করতেন। গ্রেপ্তারের পর তাঁকে সুধারাম থানায় সোপর্দ করা হয়। সুধারাম থানা-পুলিশ ওই নারীর করা মামলায় তাঁকে গ্রেপ্তার দেখিয়ে আজ শুক্রবার দুপুরে নোয়াখালীর চিফ জুডিশিয়াল ম্যাজিস্ট্রেট আদালতে পাঠায়। আদালত শুনানি শেষে তাঁকে জেলা কারাগারে পাঠান।</p>', 'নারীর ব্যক্তিগত ভিডিও ছড়িয়ে দেওয়ার ভয় দেখিয়ে চাঁদা দাবি, গ্রেপ্তার ১', NULL, 1, 1, 1, 1, '02-02-2024', 'February', NULL, NULL, NULL, 1, NULL, '117/নারীর-ব্যক্তিগত-ভিডিও-ছড়িয়ে-দেওয়ার-ভয়-দেখিয়ে-চাঁদা-দাবি'),
(119, 1075, 6, 27, NULL, NULL, 1, 'ভিন্ন মাস, বছর, এমনকি ভিন্ন দশকে জন্ম নিয়েও তাঁরা যমজ', NULL, NULL, 'public/postimages/65bcf9c5398fc.png', 'যমজ সন্তানের অপেক্ষায় ছিলেন আয়ারল্যান্ডের কিলকেনি শহরের বাসিন্দা ক্রিস ও মারিয়া জোনস এলিয়ট দম্পতি। সন্তান হওয়ার সম্ভাব্য তারিখ ছিল ২০১৩ সালের ২১ সেপ্টেম্বর। কিন্তু গর্ভধারণের মাত্র ২৩ সপ্তাহ পাঁচ দিনের মাথায় তলপেটে তীব্র চাপ অনুভব করেন মারিয়া। হাসপাতালে ভর্তি করা হয় তাঁকে।', '<p>যমজ সন্তানের অপেক্ষায় ছিলেন আয়ারল্যান্ডের কিলকেনি শহরের বাসিন্দা ক্রিস ও মারিয়া জোনস এলিয়ট দম্পতি। সন্তান হওয়ার সম্ভাব্য তারিখ ছিল ২০১৩ সালের ২১ সেপ্টেম্বর। কিন্তু গর্ভধারণের মাত্র ২৩ সপ্তাহ পাঁচ দিনের মাথায় তলপেটে তীব্র চাপ অনুভব করেন মারিয়া। হাসপাতালে ভর্তি করা হয় তাঁকে। ২০১৩ সালের ১ জুন জন্মগ্রহণ করে প্রথম যমজ অ্যামি। তার ওজন ছিল মাত্র আধা কেজি। সে লড়ছিল ইনকিউবেটরে। ওদিকে তার যমজ বোন ক্যাটি লড়ছিল মায়ের ডিম্বাশয়ে। অবশেষে অ্যামির জন্মের ৮৭ দিন পর, ২৭ আগস্ট জন্ম নেয় ক্যাটি।&nbsp;</p><p><span style=\"font-size: 1rem;\">যুক্তরাষ্ট্রের টেনেসি অঙ্গরাজ্যের জেফারসন সিটির দম্পতি ক্রিস্টেন ও ইয়ান মিলার। তাঁদের যমজ সন্তান হওয়ার সম্ভাব্য সময় ছিল ২০১৬ সালের জুন। কিন্তু ফেব্রুয়ারিতেই জটিলতা দেখা দেওয়ায় ক্রিস্টেনকে হাসপাতালে ভর্তি করা হয়। ২০১৬ সালের ১৪ ফেব্রুয়ারি গর্ভধারণের ২৪ সপ্তাহ এক দিনের মাথায় জন্ম নেয় যমজ পুত্র মিকা। ঘণ্টাখানেকের মধ্যে মিকার যমজ বোন মেডিলিনও চলে আসবে—এমনটাই প্রত্যাশা করছিলেন চিকিৎসক। তবে কিছুক্ষণের মধ্যেই তিনি বুঝতে পারেন, মেডিলিনের জন্ম শিগগিরই হচ্ছে না। অবশেষে মিকার জন্মের ৩৮ দিন পর পৃথিবীতে আসে মেডিলিন।&nbsp;</span><br></p>', 'ভিন্ন মাস, বছর, এমনকি ভিন্ন দশকে জন্ম নিয়েও তাঁরা যমজ', NULL, 1, 1, 1, 1, '02-02-2024', 'February', NULL, NULL, NULL, 1, NULL, '119/ভিন্ন-মাস,-বছর,-এমনকি-ভিন্ন-দশকে-জন্ম-নিয়েও-তাঁরা-যমজ'),
(120, 758, 6, 27, NULL, NULL, 1, 'ইয়েমেনে হুতিদের ৩৬ লক্ষ্যবস্তুতে হামলার কারণ জানাল', NULL, NULL, 'public/postimages/65bf10ffa9bab.png', 'ইরাক ও সিরিয়ায় ইরানের ৮৫ লক্ষ্যবস্তুতে হামলার পর এবার ইয়েমেনে যুক্তরাজ্যের সঙ্গে যৌথ হামলা চালাল যুক্তরাষ্ট্র।', '<p>ইরাক ও সিরিয়ায় ইরানের ৮৫ লক্ষ্যবস্তুতে হামলার পর এবার ইয়েমেনে যুক্তরাজ্যের সঙ্গে যৌথ হামলা চালাল যুক্তরাষ্ট্র। গতকাল শনিবার রাতে ইয়েমেনের ১৩টি জায়গায় ইরান–সমর্থিত হুতি বিদ্রোহীদের ৩৬টি লক্ষ্যবস্তুতে হামলা চালানো হয়েছে।ইরাক ও সিরিয়ায় ইরানের ৮৫ লক্ষ্যবস্তুতে হামলার পর এবার ইয়েমেনে যুক্তরাজ্যের সঙ্গে যৌথ হামলা চালাল যুক্তরাষ্ট্র। গতকাল শনিবার রাতে ইয়েমেনের ১৩টি জায়গায় ইরান–সমর্থিত হুতি বিদ্রোহীদের ৩৬টি লক্ষ্যবস্তুতে হামলা চালানো হয়েছে।ইরাক ও সিরিয়ায় ইরানের ৮৫ লক্ষ্যবস্তুতে হামলার পর এবার ইয়েমেনে যুক্তরাজ্যের সঙ্গে যৌথ হামলা চালাল যুক্তরাষ্ট্র। গতকাল শনিবার রাতে ইয়েমেনের ১৩টি জায়গায় ইরান–সমর্থিত হুতি বিদ্রোহীদের ৩৬টি লক্ষ্যবস্তুতে হামলা চালানো হয়েছে।ইরাক ও সিরিয়ায় ইরানের ৮৫ লক্ষ্যবস্তুতে হামলার পর এবার ইয়েমেনে যুক্তরাজ্যের সঙ্গে যৌথ হামলা চালাল যুক্তরাষ্ট্র। গতকাল শনিবার রাতে ইয়েমেনের ১৩টি জায়গায় ইরান–সমর্থিত হুতি বিদ্রোহীদের ৩৬টি লক্ষ্যবস্তুতে হামলা চালানো হয়েছে।ইরাক ও সিরিয়ায় ইরানের ৮৫ লক্ষ্যবস্তুতে হামলার পর এবার ইয়েমেনে যুক্তরাজ্যের সঙ্গে যৌথ হামলা চালাল যুক্তরাষ্ট্র। গতকাল শনিবার রাতে ইয়েমেনের ১৩টি জায়গায় ইরান–সমর্থিত হুতি বিদ্রোহীদের ৩৬টি লক্ষ্যবস্তুতে হামলা চালানো হয়েছে।ইরাক ও সিরিয়ায় ইরানের ৮৫ লক্ষ্যবস্তুতে হামলার পর এবার ইয়েমেনে যুক্তরাজ্যের সঙ্গে যৌথ হামলা চালাল যুক্তরাষ্ট্র। গতকাল শনিবার রাতে ইয়েমেনের ১৩টি জায়গায় ইরান–সমর্থিত হুতি বিদ্রোহীদের ৩৬টি লক্ষ্যবস্তুতে হামলা চালানো হয়েছে।ইরাক ও সিরিয়ায় ইরানের ৮৫ লক্ষ্যবস্তুতে হামলার পর এবার ইয়েমেনে যুক্তরাজ্যের সঙ্গে যৌথ হামলা চালাল যুক্তরাষ্ট্র। গতকাল শনিবার রাতে ইয়েমেনের ১৩টি জায়গায় ইরান–সমর্থিত হুতি বিদ্রোহীদের ৩৬টি লক্ষ্যবস্তুতে হামলা চালানো হয়েছে।ইরাক ও সিরিয়ায় ইরানের ৮৫ লক্ষ্যবস্তুতে হামলার পর এবার ইয়েমেনে যুক্তরাজ্যের সঙ্গে যৌথ হামলা চালাল যুক্তরাষ্ট্র। গতকাল শনিবার রাতে ইয়েমেনের ১৩টি জায়গায় ইরান–সমর্থিত হুতি বিদ্রোহীদের ৩৬টি লক্ষ্যবস্তুতে হামলা চালানো হয়েছে।