(123, 754, 9, 30, NULL, NULL, 1, 'দেশে তৈরি নতুন মডেলের ল্যাপটপ এনেছে ইনফিনিক্স', NULL, NULL, 'public/postimages/65bf169ee43a4.png', 'বাংলাদেশে তৈরি নতুন মডেলের ল্যাপটপ বাজারে এনেছে ইনফিনিক্স। উইন্ডোজ ১১ অপারেটিং সিস্টেমে চলা', '<p>বাংলাদেশে তৈরি নতুন মডেলের ল্যাপটপ বাজারে এনেছে ইনফিনিক্স। উইন্ডোজ ১১ অপারেটিং সিস্টেমে চলা ‘ইনবুক এক্স২’ মডেলের ল্যাপটপটিতে ইন্টেল কোর আই ৫ প্রসেসরসহ ৮ গিগাবাইট র‍্যাম ও ৫১২ গিগাবাইট ধারণক্ষমতা রয়েছে। ১৪ ইঞ্চি এফএইচডি (ফুল হাইডেফিনেশন) আইপিএস পর্দাযুক্ত ল্যাপটপটির দাম ধরা হয়েছে ৬১ হাজার ৯৯০ টাকা। এক সংবাদ বিজ্ঞপ্তিতে এ তথ্য জানিয়েছে ইনফিনিক্স বাংলাদেশ।বাংলাদেশে তৈরি নতুন মডেলের ল্যাপটপ বাজারে এনেছে ইনফিনিক্স। উইন্ডোজ ১১ অপারেটিং সিস্টেমে চলা ‘ইনবুক এক্স২’ মডেলের ল্যাপটপটিতে ইন্টেল কোর আই ৫ প্রসেসরসহ ৮ গিগাবাইট র‍্যাম ও ৫১২ গিগাবাইট ধারণক্ষমতা রয়েছে। ১৪ ইঞ্চি এফএইচডি (ফুল হাইডেফিনেশন) আইপিএস পর্দাযুক্ত ল্যাপটপটির দাম ধরা হয়েছে ৬১ হাজার ৯৯০ টাকা। এক সংবাদ বিজ্ঞপ্তিতে এ তথ্য জানিয়েছে ইনফিনিক্স বাংলাদেশ।বাংলাদেশে তৈরি নতুন মডেলের ল্যাপটপ বাজারে এনেছে ইনফিনিক্স। উইন্ডোজ ১১ অপারেটিং সিস্টেমে চলা ‘ইনবুক এক্স২’ মডেলের ল্যাপটপটিতে ইন্টেল কোর আই ৫ প্রসেসরসহ ৮ গিগাবাইট র‍্যাম ও ৫১২ গিগাবাইট ধারণক্ষমতা রয়েছে। ১৪ ইঞ্চি এফএইচডি (ফুল হাইডেফিনেশন) আইপিএস পর্দাযুক্ত ল্যাপটপটির দাম ধরা হয়েছে ৬১ হাজার ৯৯০ টাকা। এক সংবাদ বিজ্ঞপ্তিতে এ তথ্য জানিয়েছে ইনফিনিক্স বাংলাদেশ।বাংলাদেশে তৈরি নতুন মডেলের ল্যাপটপ বাজারে এনেছে ইনফিনিক্স। উইন্ডোজ ১১ অপারেটিং সিস্টেমে চলা ‘ইনবুক এক্স২’ মডেলের ল্যাপটপটিতে ইন্টেল কোর আই ৫ প্রসেসরসহ ৮ গিগাবাইট র‍্যাম ও ৫১২ গিগাবাইট ধারণক্ষমতা রয়েছে। ১৪ ইঞ্চি এফএইচডি (ফুল হাইডেফিনেশন) আইপিএস পর্দাযুক্ত ল্যাপটপটির দাম ধরা হয়েছে ৬১ হাজার ৯৯০ টাকা। এক সংবাদ বিজ্ঞপ্তিতে এ তথ্য জানিয়েছে ইনফিনিক্স বাংলাদেশ।বাংলাদেশে তৈরি নতুন মডেলের ল্যাপটপ বাজারে এনেছে ইনফিনিক্স। উইন্ডোজ ১১ অপারেটিং সিস্টেমে চলা ‘ইনবুক এক্স২’ মডেলের ল্যাপটপটিতে ইন্টেল কোর আই ৫ প্রসেসরসহ ৮ গিগাবাইট র‍্যাম ও ৫১২ গিগাবাইট ধারণক্ষমতা রয়েছে। ১৪ ইঞ্চি এফএইচডি (ফুল হাইডেফিনেশন) আইপিএস পর্দাযুক্ত ল্যাপটপটির দাম ধরা হয়েছে ৬১ হাজার ৯৯০ টাকা। এক সংবাদ বিজ্ঞপ্তিতে এ তথ্য জানিয়েছে ইনফিনিক্স বা